import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 961:
        return {"target": pos, "stop": None, "take": None}

    # Donchian breakout parameters
    lookback = 96
    atr_period = 14
    trend_filter_period = 50

    # Calculate Donchian channels
    high_96 = ind.highest(hist.high, lookback)
    low_96 = ind.lowest(hist.low, lookback)

    # Calculate ATR
    atr = ind.atr(hist, atr_period)

    # Calculate 50 EMA for trend filter
    ema_50 = ind.ema(hist.close, trend_filter_period)

    # Determine trend direction
    if hist.close[-1] > ema_50[-1]:
        trend = 1  # Long
    elif hist.close[-1] < ema_50[-1]:
        trend = -1  # Short
    else:
        trend = 0  # Flat

    # Check for breakout
    if trend == 1 and hist.close[-1] > high_96[-1]:
        if 'entry_price' not in state:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = atr[-1]
            state['target'] = 0.5
            state['stop'] = state['entry_price'] - 2 * state['entry_atr']
            state['take'] = state['entry_price'] + 6 * state['entry_atr']
        else:
            if hist.close[-1] >= state['entry_price'] + state['entry_atr']:
                state['target'] += 0.5
                state['stop'] = state['entry_price'] - 2 * state['entry_atr']
                state['take'] = state['entry_price'] + 6 * state['entry_atr']
                if state['target'] > 1:
                    state['target'] = 1
    elif trend == -1 and hist.close[-1] < low_96[-1]:
        if 'entry_price' not in state:
            state['entry_price'] = hist.close[-1]
            state['entry_atr'] = atr[-1]
            state['target'] = -0.5
            state['stop'] = state['entry_price'] + 2 * state['entry_atr']
            state['take'] = state['entry_price'] - 6 * state['entry_atr']
        else:
            if hist.close[-1] <= state['entry_price'] - state['entry_atr']:
                state['target'] -= 0.5
                state['stop'] = state['entry_price'] + 2 * state['entry_atr']
                state['take'] = state['entry_price'] - 6 * state['entry_atr']
                if state['target'] < -1:
                    state['target'] = -1

    # Check for opposite Donchian signal
    if trend == 1 and hist.close[-1] < low_96[-1]:
        state = {}
    elif trend == -1 and hist.close[-1] > high_96[-1]:
        state = {}

    # Ensure target is on 0.05 grid
    state['target'] = round(state['target'], 2)

    return {"target": state['target'], "stop": state['stop'], "take": state['take']}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    if len(hist) < 32:
        return {"target": pos, "stop": None, "take": None}

    # Calculate the 32-bar range box
    box_top = ind.highest(hist.close, 32)[-1]
    box_bottom = ind.lowest(hist.close, 32)[-1]
    box_height = box_top - box_bottom

    # Calculate the entry ATR
    entry_atr = ind.atr(hist, 14)[-1]

    # Check if the box height is at most 3 times ATR
    if box_height > 3 * entry_atr:
        return {"target": pos, "stop": None, "take": None}

    # Check if we are flat and haven't hit the 2 entries per UTC day cap
    if pos == 0 and state.get('entries_today', 0) < 2:
        # Check if the price is above the box top
        if hist.close[-1] > box_top:
            # Calculate the target position size
            target_size = max(0.05, min(1.0, 0.0025 * hist.close[-1] / entry_atr))
            # Set the hard stop and take profit levels
            stop_price = box_top - 2 * entry_atr
            take_price = box_top + 4 * entry_atr
            # Update the state to count the entry for the day
            state['entries_today'] = state.get('entries_today', 0) + 1
            return {"target": target_size, "stop": stop_price, "take": take_price}

    # If no entry conditions are met, return no change
    return {"target": pos, "stop": None, "take": None}
